export const getTextWidth = (element) => {
    const ctx = computeContextStyle(element);
    return getStringWidthFromContext(ctx);
};
export const getComputedFont = (element) => {
    const { fontWeight, fontSize, fontFamily } = window.getComputedStyle(element);
    return `${fontWeight} ${fontSize} ${fontFamily}`;
};
export const getStringWidthFromContext = (ctx) => (t) => ctx.measureText(t).width;
const computeContextStyle = (element) => {
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    ctx.font = getComputedFont(element);
    return ctx;
};
